def drop_empty(dict1):
    """Drop empty items from a given dictionary.

    Items whose value is None or has length zero (for example
    '', [], {}, () or set()) are dropped. Values such as 0 and
    False, which are falsy but not empty, are kept, and the
    original dictionary is not modified.
    """

    def is_empty(value):
        if value is None:
            return True
        try:
            return len(value) == 0
        except TypeError:
            return False

    return {key: value for key, value in dict1.items() if not is_empty(value)}
